/* ===== geometry.js ===== */
// Geometria: interpolazione tra emozioni, spostamento controllato dei punti, colori

function lerp(a, b, t) {
  return a + (b - a) * t;
}

// Interpola i contorni condivisi tra le emozioni usando i pesi
// glyfs = array per emozione di { c: [[[x,y],...]], a: advance }
// weights = array parallelo di pesi (somma ~1)
function interpolateGlyph(glyfs, weights) {
  const n = glyfs.length;
  // Pesano solo i master che hanno davvero il glifo (es. è/é sono vuoti in Neutro):
  // se il master dominante manca del glifo, i pesi vengono rinormalizzati
  // sui master che lo possiedono, evitando glifi invisibili.
  const active = glyfs.map((g, i) => (g && g.c && g.c.length ? weights[i] : 0));
  const activeSum = active.reduce((a, b) => a + b, 0);
  const w = activeSum > 0 ? active.map((a) => a / activeSum) : weights;
  const ref = glyfs.find((g) => g.c && g.c.length);
  if (!ref) return { contours: [], advance: 360 };
  const contourCount = ref.c.length;
  const contours = [];
  let advance = 0;
  for (let i = 0; i < n; i++) advance += (glyfs[i] ? glyfs[i].a : 360) * w[i];
  for (let ci = 0; ci < contourCount; ci++) {
    const count = ref.c[ci].length;
    const out = new Array(count);
    for (let j = 0; j < count; j++) {
      let x = 0, y = 0;
      for (let i = 0; i < n; i++) {
        const g = glyfs[i];
        if (g && g.c && g.c[ci] && g.c[ci][j]) {
          x += g.c[ci][j][0] * w[i];
          y += g.c[ci][j][1] * w[i];
        }
      }
      out[j] = [x, y];
    }
    contours.push(out);
  }
  return { contours, advance };
}

// Pesi delle emozioni a partire dalla posizione sul pad (valenza×arousal)
// Inverse distance squared: al punto esatto di un'emozione peso = 1
function weightsFromPad(x, y, emotions) {
  const raw = emotions.map((e) => {
    const dx = x - e.pad.x;
    const dy = y - e.pad.y;
    const d2 = dx * dx + dy * dy;
    return 1 / (d2 + 1e-6);
  });
  const sum = raw.reduce((a, b) => a + b, 0) || 1;
  return raw.map((w) => w / sum);
}

// Posizione sul pad che produce dati pesi (inversa approssimata di weightsFromPad).
// La funzione diretta (inverse distance squared) non copre tutte le misture:
// per quelle irraggiungibili si cerca il punto che minimizza l'errore massimo
// sul singolo peso. Ricerca a griglia grossolana → fine (coarse-to-fine).
function weightsToPad(weights, emotions) {
  const target = weights.map((w) => w);
  const err = (px, py) => {
    const w = weightsFromPad(px, py, emotions);
    let m = 0;
    for (let i = 0; i < w.length; i++) {
      const d = Math.abs(w[i] - target[i]);
      if (d > m) m = d;
    }
    return m;
  };
  let best = { e: Infinity, x: 0, y: 0 };
  let cx = 0, cy = 0, half = 1;
  for (let pass = 0; pass < 8; pass++) {
    const n = 21;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        const x = Math.max(-1, Math.min(1, cx - half + (2 * half * i) / (n - 1)));
        const y = Math.max(-1, Math.min(1, cy - half + (2 * half * j) / (n - 1)));
        const e = err(x, y);
        if (e < best.e) best = { e, x, y };
      }
    }
    cx = best.x; cy = best.y;
    half = (2 * half) / (n - 1);
  }
  return { x: best.x, y: best.y };
}

function blendColor(emotions, weights) {
  // l'ancora "neutra" non ha colore: mescola solo le emozioni reali
  let wSum = 0;
  for (let i = 0; i < emotions.length; i++) {
    if (!emotions[i].neutral) wSum += weights[i];
  }
  let r = 1, g = 1, b = 1;
  if (wSum > 0) {
    const inv = 1 / wSum;
    for (let i = 0; i < emotions.length; i++) {
      const e = emotions[i];
      if (e.neutral) continue;
      const w = weights[i] * inv;
      if (w <= 0) continue;
      r *= Math.pow(e.rgb.r, w);
      g *= Math.pow(e.rgb.g, w);
      b *= Math.pow(e.rgb.b, w);
    }
  } else {
    r = 0; g = 0; b = 0;
  }
  // neutralità: quanto pesa l'ancora "Neutro" (al centro del quadrato ~1, su
  // un'emozione ~0): al neutro il colore vira gradualmente al nero pieno,
  // coerente con il font TTF monocromatico.
  let t = 0;
  for (let i = 0; i < emotions.length; i++) {
    if (emotions[i].neutral) t = weights[i];
  }
  if (t > 0) {
    r *= 1 - t;
    g *= 1 - t;
    b *= 1 - t;
  }
  r = Math.round(Math.min(255, Math.max(0, r)));
  g = Math.round(Math.min(255, Math.max(0, g)));
  b = Math.round(Math.min(255, Math.max(0, b)));
  return { r, g, b, hex: rgbToHex(r, g, b) };
}

function rgbToHex(r, g, b) {
  return "#" + ((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1);
}

// Nome dell'emozione dominante dato il peso
function dominantEmotion(emotions, weights) {
  let best = 0;
  for (let i = 1; i < weights.length; i++) if (weights[i] > weights[best]) best = i;
  return emotions[best].id;
}

const EMOTION_DESC = {
  Noia: "Energia minima; il tono spento che risucchia il colore dall'ambiente.",
  Tristezza: "Il colore del \"freddo\"; bassa energia e tende a recedere visivamente.",
  Felicita: "La \"luce solare\" di base; energia positiva ma non eccessiva.",
  Sorpresa: "Il colore dello \"shock\"; risalta perché è una tinta innaturale ed elettrica.",
  Ansia: "Alta tensione ma instabile; una versione \"malaticcia\" della felicità.",
  Rabbia: "Energia massima; il colore dell'incendio o dell'allarme."
};

function dominantEmotionId(weights) {
  let best = -1;
  let bw = -1;
  for (let i = 0; i < store.emotions.length; i++) {
    if (store.emotions[i].neutral) continue;
    if (weights[i] > bw) { bw = weights[i]; best = i; }
  }
  if (best < 0 || bw <= 0) return null;
  return { id: store.emotions[best].id, weight: bw };
}

const meshColors = () => NEO_DATA.meta.emotions.filter((e) => !e.neutral).map((e) => e.color);

const mesh = (function () {
  if (typeof window === "undefined" || typeof requestAnimationFrame === "undefined") return null;
  const canvas = document.getElementById("mesh");
  if (!canvas || typeof canvas.getContext !== "function") return null;
  const ctx = canvas.getContext("2d");
  let w = 0, h = 0;
  let weights = meshColors().map(() => 1 / Math.max(1, meshColors().length));
  let tint = null;
  let tintStrength = 0;
  let blobs = [];
  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = window.innerWidth;
    h = window.innerHeight;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = w + "px";
    canvas.style.height = h + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  function seed() {
    const cols = meshColors();
    if (!cols.length) return;
    blobs = cols.map((c, i) => ({
      x: [0.16, 0.86, 0.8, 0.2, 0.06, 0.94][i % 6] * w,
      y: [0.2, 0.16, 0.82, 0.84, 0.5, 0.5][i % 6] * h,
      r: 0.28 * Math.min(w, h),
      phase: i * 1.7,
      fx: 0.00022 + i * 0.000013,
      fy: 0.00019 + i * 0.000017,
      fr: 0.00031 + i * 0.000011
    }));
  }
  function rgba(hex, a) {
    const c = hex.replace("#", "");
    const r = parseInt(c.slice(0, 2), 16);
    const g = parseInt(c.slice(2, 4), 16);
    const b = parseInt(c.slice(4, 6), 16);
    return `rgba(${r},${g},${b},${a})`;
  }
  function frame(t) {
    const cols = meshColors();
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, w, h);
    if (tint) {
      ctx.fillStyle = rgba(tint, 0.08 + 0.36 * tintStrength);
      ctx.fillRect(0, 0, w, h);
    }
    if (!cols.length) return;
    if (!blobs.length) seed();
    const tt = t / 1000;
    for (let i = 0; i < blobs.length; i++) {
      const b = blobs[i];
      const col = cols[i % cols.length];
      const wgt = weights[i % weights.length] || 0;
      const x = b.x + Math.sin(tt * b.fx + b.phase) * 0.08 * w;
      const y = b.y + Math.cos(tt * b.fy + b.phase * 1.3) * 0.08 * h;
      const r = b.r * (0.35 + 1.6 * Math.pow(wgt, 0.6) + 0.07 * Math.sin(tt * b.fr + b.phase * 2));
      const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
      grad.addColorStop(0, rgba(col, 0.18 + 0.58 * Math.pow(wgt, 0.55)));
      grad.addColorStop(1, rgba(col, 0));
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  let raf = 0;
  function loop(t) {
    frame(t);
    raf = requestAnimationFrame(loop);
  }
  window.addEventListener("resize", () => { resize(); blobs = []; });
  resize();
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    frame(0);
  } else {
    raf = requestAnimationFrame(loop);
  }
  return {
    setWeights(wgt) {
      const norm = wgt.slice(0, 6);
      const sum = norm.reduce((a, b) => a + b, 0) || 1;
      weights = norm.map((v) => v / sum);
    },
    setTint(hex, strength) { tint = hex; tintStrength = strength || 0; }
  };
})();

function shade(hex, pct) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const p = Math.abs(pct);
  const t = pct < 0 ? 0 : 255;
  r = Math.round((t - r) * p + r);
  g = Math.round((t - g) * p + g);
  b = Math.round((t - b) * p + b);
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

function updateEmotionTheme(opts) {
  opts = opts || {};
  let weights = null;
  if (opts.emotionId && store.emotions.length) {
    weights = store.emotions.map((e) => (e.id === opts.emotionId ? 1 : 0));
  } else if (typeof getWeights === "function") {
    try { weights = getWeights(); } catch (e) { weights = null; }
  }
  let dominant = null;
  let strength = 0;
  if (weights) {
    const d = dominantEmotionId(weights);
    if (d && d.weight >= 0.5) dominant = d;
    let neu = 0;
    for (let i = 0; i < store.emotions.length; i++) {
      if (store.emotions[i].neutral) neu = weights[i] || 0;
    }
    strength = Math.max(0, Math.min(1, 1 - neu));
  }
  const sub = document.querySelector ? document.querySelector(".subtitle") : null;
  if (sub) {
    if (!sub.dataset.defaultText) sub.dataset.defaultText = sub.textContent;
    if (dominant && EMOTION_DESC[dominant.id]) {
      sub.textContent = dominant.id + ": " + EMOTION_DESC[dominant.id];
    } else {
      sub.textContent = sub.dataset.defaultText;
    }
  }
  let tint = null;
  if (opts.color) tint = opts.color;
  else if (typeof currentColor === "function") {
    try { tint = currentColor(); } catch (e) { tint = null; }
  }
  if (mesh) {
    if (weights) mesh.setWeights(weights);
    if (tint) mesh.setTint(tint, strength);
  }
  if (document.documentElement && document.documentElement.style) {
    if (tint && strength >= 0.15) {
      document.documentElement.style.setProperty("--accent", tint);
      document.documentElement.style.setProperty("--accent-deep", shade(tint, -0.16));
    } else {
      document.documentElement.style.setProperty("--accent", "#1a1a1a");
      document.documentElement.style.setProperty("--accent-deep", "#000000");
    }
  }
}

/* ------------------------- spostamento controllato ------------------------- */

function pointSegmentDist(px, py, ax, ay, bx, by) {
  const dx = bx - ax, dy = by - ay;
  const l2 = dx * dx + dy * dy;
  if (l2 < 1e-9) return Math.hypot(px - ax, py - ay);
  let t = ((px - ax) * dx + (py - ay) * dy) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

// Trasforma i tratti dell'utente in spostamenti dei punti condivisi.
// strokes = array di { pts: [[x,y],...] (in unità font), radius, force }
// Ritorna deltas con la stessa struttura dei contorni.
function strokesToDeltas(contours, strokes) {
  const deltas = contours.map((c) => c.map(() => [0, 0]));
  for (const stroke of strokes) {
    const pts = stroke.pts;
    if (pts.length < 2) continue;
    const radius = stroke.radius;
    const force = stroke.force;
    for (let k = 0; k < pts.length - 1; k++) {
      const ax = pts[k][0], ay = pts[k][1];
      const bx = pts[k + 1][0], by = pts[k + 1][1];
      const dx = bx - ax, dy = by - ay;
      const len = Math.hypot(dx, dy);
      if (len < 1e-6) continue;
      const ux = dx / len, uy = dy / len;
      for (let ci = 0; ci < contours.length; ci++) {
        const c = contours[ci];
        for (let j = 0; j < c.length; j++) {
          const px = c[j][0], py = c[j][1];
          const d = pointSegmentDist(px, py, ax, ay, bx, by);
          if (d > radius) continue;
          const fall = 1 - d / radius;
          const push = force * fall * fall;
          deltas[ci][j][0] += ux * push;
          deltas[ci][j][1] += uy * push;
        }
      }
    }
  }
  // limita lo spostamento massimo per punto
  const maxMove = 90;
  for (const c of deltas) {
    for (const d of c) {
      const m = Math.hypot(d[0], d[1]);
      if (m > maxMove) {
        d[0] *= maxMove / m;
        d[1] *= maxMove / m;
      }
    }
  }
  return deltas;
}

// Spostamento diretto dei punti condivisi (modalità "Punti").
// moves = array di { ci, j, dx, dy, radius }: il punto (ci,j) trascinato di
// (dx,dy) trascina con sé i punti vicini con falloff (1 - d/radius)^2.
// Ritorna deltas con la stessa struttura dei contorni.
function pointMovesToDeltas(contours, moves) {
  const deltas = contours.map((c) => c.map(() => [0, 0]));
  for (const mv of moves) {
    const anchor = contours[mv.ci] ? contours[mv.ci][mv.j] : null;
    if (!anchor) continue;
    const ax = anchor[0], ay = anchor[1];
    const dx = mv.dx || 0, dy = mv.dy || 0;
    const radius = Math.max(1, mv.radius || 70);
    for (let ci = 0; ci < contours.length; ci++) {
      const c = contours[ci];
      for (let j = 0; j < c.length; j++) {
        const px = c[j][0], py = c[j][1];
        const d = Math.hypot(px - ax, py - ay);
        if (d > radius) continue;
        const fall = 1 - d / radius;
        const push = fall * fall;
        deltas[ci][j][0] += dx * push;
        deltas[ci][j][1] += dy * push;
      }
    }
  }
  const maxMove = 90;
  for (const c of deltas) {
    for (const d of c) {
      const m = Math.hypot(d[0], d[1]);
      if (m > maxMove) {
        d[0] *= maxMove / m;
        d[1] *= maxMove / m;
      }
    }
  }
  return deltas;
}

function applyDeltas(contours, deltas) {
  return contours.map((c, ci) => c.map((p, j) => {
    const d = deltas[ci] ? deltas[ci][j] : null;
    return d ? [p[0] + d[0], p[1] + d[1]] : [p[0], p[1]];
  }));
}

// Media di più contributi (stessa struttura di deltas)
function meanDeltas(list) {
  if (!list.length) return null;
  const ref = list[0];
  const out = ref.map((c) => c.map(() => [0, 0]));
  for (const item of list) {
    for (let ci = 0; ci < out.length && ci < item.length; ci++) {
      for (let j = 0; j < out[ci].length && j < item[ci].length; j++) {
        out[ci][j][0] += item[ci][j][0];
        out[ci][j][1] += item[ci][j][1];
      }
    }
  }
  const n = list.length;
  return out.map((c) => c.map((d) => [d[0] / n, d[1] / n]));
}
/* ===== store.js ===== */
// Caricamento dei dati generati dalla pipeline (app/data)

let meta = null;
let masters = {};

const DATA_DIR = "data";

// Normalizza il carattere immesso: maiuscole per le lettere, minuscole per gli accenti
function normalizeChar(ch) {
  if (ch === " ") return " ";
  const upper = ch.toUpperCase();
  if (/[A-Z]/.test(upper) && upper.length === 1) return upper;
  if (meta.charset.includes(ch)) return ch;
  return null;
}

function glyphsForChar(ch) {
  // restituisce, nell'ordine delle emozioni, {c, a} per il carattere
  const out = [];
  for (const e of meta.emotions) {
    const g = masters[e.id][ch];
    out.push(g || { c: [], a: 360 });
  }
  return out;
}

function hexToRgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

const store = {
  get meta() { return meta; },
  get masters() { return masters; },
  normalizeChar,
  glyphsForChar,
  get charset() { return meta ? meta.charset : []; },
  get emotions() { return meta ? meta.emotions : []; },
  get visibleEmotions() { return meta ? meta.emotions.filter((e) => !e.neutral) : []; },
  get pointsPerContour() { return meta ? meta.pointsPerContour : { outer: 768, hole: 320 }; },
};

// per far funzionare sia come modulo import in main che in altri punti
const storeModule = store;
store.load = async function () {
  meta = NEO_DATA.meta;
  masters = NEO_DATA.masters;
  for (const e of meta.emotions) e.rgb = hexToRgb(e.color);
  return store;
};
/* ===== community.js ===== */
// Memoria dei contributi (locale, per ora sul singolo computer).
// Ogni contributo è legato all'emozione in cui è stato creato:
// neoalfabeto.contributions.<char> = { "<emozione>": [deltas, ...], ... }

const PREFIX = "neoalfabeto.contributions.";

function key(char) {
  return PREFIX + char;
}

function parseStore(char) {
  try {
    const raw = localStorage.getItem(key(char));
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return {};
    return parsed;
  } catch {
    return {};
  }
}

function listContributions(char, emotion) {
  const obj = parseStore(char);
  return Array.isArray(obj[emotion]) ? obj[emotion] : [];
}

function addContribution(char, emotion, deltas) {
  const obj = parseStore(char);
  const list = Array.isArray(obj[emotion]) ? obj[emotion] : [];
  list.push(deltas);
  obj[emotion] = list;
  try {
    localStorage.setItem(key(char), JSON.stringify(obj));
  } catch (e) {
    if (list.length > 1) {
      list.shift();
      try { localStorage.setItem(key(char), JSON.stringify(obj)); } catch {}
    }
  }
  return list.length;
}

function contributionCount(char, emotion) {
  return listContributions(char, emotion).length;
}

function contributionMean(char, emotion) {
  const list = listContributions(char, emotion);
  return list.length ? meanDeltas(list) : null;
}

function countsByEmotion(char) {
  const obj = parseStore(char);
  const out = {};
  for (const k of Object.keys(obj)) {
    if (Array.isArray(obj[k]) && obj[k].length) out[k] = obj[k].length;
  }
  return out;
}

function clearContributions(char, emotion) {
  const obj = parseStore(char);
  delete obj[emotion];
  if (Object.keys(obj).length === 0) localStorage.removeItem(key(char));
  else localStorage.setItem(key(char), JSON.stringify(obj));
}

function clearAllContributions() {
  const toRemove = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (k && k.startsWith(PREFIX)) toRemove.push(k);
  }
  for (const k of toRemove) localStorage.removeItem(k);
}

const community = {
  listContributions,
  addContribution,
  contributionCount,
  contributionMean,
  countsByEmotion,
  clearContributions,
  clearAllContributions,
};
/* ===== export.js ===== */
// Esportazione: SVG (lettera, parola, alfabeto) e font TTF generato in browser

const UPM = 1000;

function contourBBox(contours) {
  let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
  for (const c of contours) for (const [x, y] of c) {
    if (x < xmin) xmin = x; if (x > xmax) xmax = x;
    if (y < ymin) ymin = y; if (y > ymax) ymax = y;
  }
  return { xmin, ymin, xmax, ymax };
}

// Path in coordinate di schermo: y capovolto (le lettere salgono verso l'alto)
function contoursToD(contours, dx = 0, dy = 0) {
  const parts = [];
  for (const c of contours) {
    if (!c.length) continue;
    parts.push(`M${r(c[0][0] + dx)} ${r(-(c[0][1] + dy))}`);
    for (let j = 1; j < c.length; j++) {
      parts.push(`L${r(c[j][0] + dx)} ${r(-(c[j][1] + dy))}`);
    }
    parts.push("Z");
  }
  return parts.join(" ");
}

const r = (v) => Math.round(v * 100) / 100;

function svgWrapper(inner, viewW, viewH, color) {
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${viewW} ${viewH}" width="${viewW}" height="${viewH}">
  <rect width="100%" height="100%" fill="#ffffff"/>
  <g fill="${color}" stroke="${color}" stroke-width="1">
${inner}
  </g>
</svg>`;
}

function exportLetter(glyph, color) {
  const b = contourBBox(glyph.contours);
  const pad = 40;
  const viewW = Math.max(300, b.xmax - b.xmin + pad * 2);
  const viewH = 900;
  const dx = (viewW - (b.xmax + b.xmin)) / 2;
  const dy = 60; // margine sotto la baseline
  const d = contoursToD(glyph.contours, dx, dy);
  const inner = `    <path d="${d}"/>`;
  return svgWrapper(inner, viewW, viewH, color);
}

function exportWord(items, color) {
  // items: [{ contours, advance }]
  let x = 0;
  const cells = [];
  for (const it of items) {
    if (it) {
      cells.push({ d: contoursToD(it.contours, x, 60), adv: it.advance });
    } else {
      cells.push({ d: "", adv: 360 });
    }
    x += it ? it.advance : 360;
  }
  const viewW = Math.max(300, x + 80);
  const viewH = 900;
  const inner = cells.map((c) => `    <path d="${c.d}"/>`).join("\n");
  return svgWrapper(inner, viewW, viewH, color);
}

function exportAlphabet(chars, resolveGlyph, color) {
  const cols = 18;
  const cellW = 170, cellH = 860;
  const inner = [];
  chars.forEach((ch, i) => {
    const g = resolveGlyph(ch);
    if (!g || !g.contours.length) return;
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x0 = col * cellW + 25;
    const y0 = row * cellH;
    const b = contourBBox(g.contours);
    const scale = Math.min(120 / Math.max(g.advance, 1), 760 / Math.max(b.ymax - b.ymin, 1));
    const sc = (pt) => [x0 + (pt[0] - b.xmin) * scale, y0 + 700 - (pt[1] - b.ymin) * scale + 60];
    const d = g.contours.map((c) =>
      c.map((p, j) => {
        const [sx, sy] = sc(p);
        return (j === 0 ? "M" : "L") + r(sx) + " " + r(sy);
      }).join(" ") + "Z"
    ).join(" ");
    inner.push(`    <path d="${d}"/>`);
  });
  const rows = Math.ceil(chars.length / cols);
  const viewW = cols * cellW + 20;
  const viewH = rows * cellH + 20;
  return svgWrapper(inner.join("\n"), viewW, viewH, color);
}

/* ------------------------------ font TTF ------------------------------ */

const GLYPH_NAMES = {
  " ": "space", ".": "period", ",": "comma", "!": "exclam", "?": "question",
  "-": "hyphen", ";": "semicolon", ":": "colon", '"': "quotedbl",
  "(": "parenleft", ")": "parenright", "*": "asterisk", "'": "quotesingle",
};

function buildFont(resolveGlyph, charset = storeModule.charset) {
  const glyphs = [];
  const seen = new Set();

  for (const ch of charset) {
    if (seen.has(ch)) continue;
    seen.add(ch);
    const g = resolveGlyph(ch);
    const advance = g ? Math.max(1, Math.round(g.advance)) : 360;
    if (ch === " ") {
      glyphs.push(new opentype.Glyph({ name: "space", unicode: 0x20, advanceWidth: advance }));
      continue;
    }
    const path = new opentype.Path();
    const contours = g ? g.contours : [];
    for (const c of contours) {
      if (!c.length) continue;
      path.moveTo(c[0][0], c[0][1]);
      for (let j = 1; j < c.length; j++) path.lineTo(c[j][0], c[j][1]);
      path.close();
    }
    const name = GLYPH_NAMES[ch] || (ch === ch.toUpperCase() && /[A-Z0-9]/.test(ch) ? ch : "glyph" + ch.codePointAt(0).toString(16));
    const glyph = new opentype.Glyph({
      name,
      unicode: ch.codePointAt(0),
      advanceWidth: advance,
      path,
    });
    if (/[A-Z]/.test(ch)) glyph.addUnicode(ch.toLowerCase().codePointAt(0));
    glyphs.push(glyph);
  }

  const font = new opentype.Font({
    familyName: "Neoalfabeto Emotivo Co-creato",
    styleName: "Regular",
    unitsPerEm: UPM,
    ascender: 780,
    descender: -220,
    glyphs,
  });
  return font;
}

function download(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function downloadSvg(svgString, filename) {
  download(new Blob([svgString], { type: "image/svg+xml;charset=utf-8" }), filename);
}

function downloadFont(font, filename) {
  const ab = font.toArrayBuffer();
  download(new Blob([new Uint8Array(ab)], { type: "font/ttf" }), filename);
}
/* ===== pad.js ===== */
// Pad circumplex: valenza (sinistra→destra) × attivazione (basso→alto)
function createPad(canvas, emotions, onChange) {
  const ctx = canvas.getContext("2d");
  const PAD = 26;
  let x = 0, y = 0; // posizione -1..1
  let dragging = false;

  function toCanvas(vx, vy) {
    const w = canvas.width, h = canvas.height;
    const cx = PAD + ((vx + 1) / 2) * (w - 2 * PAD);
    const cy = h - PAD - ((vy + 1) / 2) * (h - 2 * PAD);
    return { cx, cy };
  }
  function toValue(cx, cy) {
    const w = canvas.width, h = canvas.height;
    const vx = ((cx - PAD) / (w - 2 * PAD)) * 2 - 1;
    const vy = -(((cy - PAD) / (h - 2 * PAD)) * 2 - 1);
    return { x: Math.max(-1, Math.min(1, vx)), y: Math.max(-1, Math.min(1, vy)) };
  }

  function draw() {
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // sfondo
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, w, h);

    // griglia sottile (passo 1/4 del range)
    ctx.strokeStyle = "rgba(0,0,0,.05)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 1; i <= 3; i++) {
      const vx = -1 + (2 * i) / 4;
      const p = toCanvas(vx, -1);
      ctx.moveTo(p.cx, PAD); ctx.lineTo(p.cx, h - PAD);
      const vy = -1 + (2 * i) / 4;
      const q = toCanvas(-1, vy);
      ctx.moveTo(PAD, q.cy); ctx.lineTo(w - PAD, q.cy);
    }
    ctx.stroke();

    // assi (sottili)
    ctx.strokeStyle = "rgba(0,0,0,.10)";
    ctx.lineWidth = 1;
    const hmid = toCanvas(0, 0);
    ctx.beginPath();
    ctx.moveTo(PAD, hmid.cy); ctx.lineTo(w - PAD, hmid.cy);
    ctx.moveTo(hmid.cx, PAD); ctx.lineTo(hmid.cx, h - PAD);
    ctx.stroke();

    // emozioni
    for (const e of emotions) {
      const { cx, cy } = toCanvas(e.pad.x, e.pad.y);
      ctx.beginPath();
      ctx.arc(cx, cy, 7, 0, Math.PI * 2);
      ctx.fillStyle = e.color;
      ctx.fill();
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.font = "600 10.5px sans-serif";
      ctx.textAlign = "center";
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 3;
      ctx.strokeText(italianId(e.id), cx, cy - 12);
      ctx.fillStyle = e.color;
      ctx.fillText(italianId(e.id), cx, cy - 12);
    }

    // emozione più vicina durante il drag
    if (dragging) {
      let best = null, bestD = Infinity;
      for (const e of emotions) {
        const dx = x - e.pad.x, dy = y - e.pad.y;
        const d = dx * dx + dy * dy;
        if (d < bestD) { bestD = d; best = e; }
      }
      if (best) {
        const { cx, cy } = toCanvas(best.pad.x, best.pad.y);
        ctx.beginPath();
        ctx.arc(cx, cy, 12, 0, Math.PI * 2);
        ctx.strokeStyle = best.color;
        ctx.lineWidth = 2.5;
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(0,0,0,.12)";
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    }

    // cursore
    const { cx, cy } = toCanvas(x, y);
    ctx.beginPath();
    ctx.arc(cx, cy, 13, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(0,0,0,.75)";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(cx, cy, 3, 0, Math.PI * 2);
    ctx.fillStyle = "#1d1d1b";
    ctx.fill();
  }

  function italianId(id) {
    const map = {
      Noia: "Noia", Tristezza: "Tristezza", Felicita: "Felicità",
      Sorpresa: "Sorpresa", Ansia: "Ansia", Rabbia: "Rabbia",
    };
    return map[id] || id;
  }

  function set(vx, vy, notify = true) {
    x = Math.max(-1, Math.min(1, vx));
    y = Math.max(-1, Math.min(1, vy));
    draw();
    if (notify && onChange) onChange({ x, y });
  }

  function get() { return { x, y }; }

  function posFromEvent(ev) {
    const rect = canvas.getBoundingClientRect();
    return {
      cx: (ev.clientX - rect.left) * (canvas.width / rect.width),
      cy: (ev.clientY - rect.top) * (canvas.height / rect.height),
    };
  }

  canvas.addEventListener("pointerdown", (ev) => {
    ev.preventDefault();
    canvas.setPointerCapture(ev.pointerId);
    dragging = true;
    const { cx, cy } = posFromEvent(ev);
    const v = toValue(cx, cy);
    set(v.x, v.y);
  });
  canvas.addEventListener("pointermove", (ev) => {
    if (!dragging) return;
    const { cx, cy } = posFromEvent(ev);
    const v = toValue(cx, cy);
    set(v.x, v.y);
  });
  canvas.addEventListener("pointerup", (ev) => {
    dragging = false;
    canvas.releasePointerCapture(ev.pointerId);
  });
  canvas.addEventListener("pointercancel", () => { dragging = false; });

  draw();
  return { set, get, draw };
}
/* ===== editor.js ===== */
// Editor della lettera: rendering + disegno (spostamento controllato dei punti)

// Box di riferimento verticale (unità font) per la centratura: copre
// lettere, cifre e punteggiatura (descender più profondo -230, ascender più alto 802)
const REF_MIN = -235;
const REF_MAX = 810;

function createEditor(canvas, store, getWeights, onStateChange) {
  const ctx = canvas.getContext("2d");
  let currentChar = "A";
  let pointMoves = [];
  let editing = false;
  const POINT_RADIUS = 70;
  let hover = null; // {cx, cy} in canvas px

  // Scala di rendering adattiva: ricalcolata in draw() per riempire il canvas col glifo
  let currentScale = canvas.height / (REF_MAX - REF_MIN);
  const MAX_SCALE = 0.75;

  function scale() {
    return currentScale;
  }

  // Offset di centratura: derivati dal glifo renderizzato
  let xOff = 0;
  let baselineScreen = 0;

  function buildBase() {
    const glyfs = store.glyphsForChar(currentChar);
    return interpolateGlyph(glyfs, getWeights());
  }

  function bbox(contours) {
    let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
    for (const c of contours) {
      for (const [x, y] of c) {
        if (x < xmin) xmin = x; if (x > xmax) xmax = x;
        if (y < ymin) ymin = y; if (y > ymax) ymax = y;
      }
    }
    return { xmin, ymin, xmax, ymax };
  }

  function toScreen(x, y) {
    const s = scale();
    return { sx: xOff + x * s, sy: baselineScreen - y * s };
  }
  function toFont(cx, cy) {
    const s = scale();
    return { x: (cx - xOff) / s, y: (baselineScreen - cy) / s };
  }

  function buildContours() {
    const base = interpolateGlyph(getEmotionGlyfs(currentChar), getWeights());
    const live = pointMovesToDeltas(base.contours, pointMoves);
    const contours = applyDeltas(base.contours, live);
    return { contours, advance: base.advance };
  }

  // Punto (indice contorno/punto) più vicino al cursore (soglia in px)
  function pickPoint(contours, cx, cy) {
    const th = 18;
    let best = null, bestD = th * th;
    for (let ci = 0; ci < contours.length; ci++) {
      const c = contours[ci];
      for (let j = 0; j < c.length; j++) {
        const { sx, sy } = toScreen(c[j][0], c[j][1]);
        const d = (sx - cx) * (sx - cx) + (sy - cy) * (sy - cy);
        if (d < bestD) { bestD = d; best = { ci, j }; }
      }
    }
    return best;
  }

  function draw() {
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, w, h);

    const base = interpolateGlyph(getEmotionGlyfs(currentChar), getWeights());
    const stable = base.contours;
    const b = bbox(stable);
    const margin = 24;
    if (isFinite(b.xmin) && isFinite(b.ymin)) {
      const sX = (canvas.width - 2 * margin) / Math.max(1, b.xmax - b.xmin);
      const sY = (canvas.height - 2 * margin) / Math.max(1, b.ymax - b.ymin);
      currentScale = Math.max(0.05, Math.min(sX, sY, MAX_SCALE));
      xOff = canvas.width / 2 - (b.xmin + b.xmax) / 2 * currentScale;
      baselineScreen = canvas.height / 2 + (b.ymin + b.ymax) / 2 * currentScale;
    } else {
      currentScale = canvas.height / (REF_MAX - REF_MIN);
      xOff = canvas.width / 2;
      baselineScreen = canvas.height / 2;
    }

    const { contours } = buildContours();

    // lettera
    const color = blendColor(store.emotions, getWeights());
    ctx.fillStyle = color.hex;
    ctx.strokeStyle = "rgba(0,0,0,.12)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const c of contours) {
      if (!c.length) continue;
      const { sx, sy } = toScreen(c[0][0], c[0][1]);
      ctx.moveTo(sx, sy);
      for (let j = 1; j < c.length; j++) {
        const p = toScreen(c[j][0], c[j][1]);
        ctx.lineTo(p.sx, p.sy);
      }
      ctx.closePath();
    }
    ctx.fill("evenodd");
    ctx.stroke();

    // punti condivisi (solo in modalità editing)
    if (editing) {
      const dotR = 2.1;
      for (let ci = 0; ci < contours.length; ci++) {
        const c = contours[ci];
        const bc = base.contours[ci];
        for (let j = 0; j < c.length; j++) {
          const { sx, sy } = toScreen(c[j][0], c[j][1]);
          const moved = bc ? Math.hypot(c[j][0] - bc[j][0], c[j][1] - bc[j][1]) > 0.5 : false;
          ctx.beginPath();
          ctx.arc(sx, sy, dotR, 0, Math.PI * 2);
          ctx.fillStyle = moved ? "#c7442e" : "rgba(43,33,24,.4)";
          ctx.fill();
        }
      }
      if (hover) {
        const p = pickPoint(contours, hover.cx, hover.cy);
        if (p) {
          const { sx, sy } = toScreen(contours[p.ci][p.j][0], contours[p.ci][p.j][1]);
          ctx.beginPath();
          ctx.arc(sx, sy, dotR + 3, 0, Math.PI * 2);
          ctx.strokeStyle = "rgba(199,68,46,.95)";
          ctx.lineWidth = 1.6;
          ctx.stroke();
        }
      }
    }
  }

  function pointerPos(ev) {
    const rect = canvas.getBoundingClientRect();
    return {
      cx: (ev.clientX - rect.left) * (canvas.width / rect.width),
      cy: (ev.clientY - rect.top) * (canvas.height / rect.height),
    };
  }

  let pointDrag = null;

  function startPointDrag(ev) {
    ev.preventDefault();
    canvas.setPointerCapture(ev.pointerId);
    const pos = pointerPos(ev);
    const { contours } = buildContours();
    const picked = pickPoint(contours, pos.cx, pos.cy);
    if (!picked) return;
    const p = toFont(pos.cx, pos.cy);
    pointDrag = { ...picked, startX: p.x, startY: p.y, dx: 0, dy: 0, radius: POINT_RADIUS };
    pointMoves.push(pointDrag);
    draw();
    if (onStateChange) onStateChange();
  }
  function movePointDrag(ev) {
    const pos = pointerPos(ev);
    hover = pos;
    if (pointDrag) {
      const p = toFont(pos.cx, pos.cy);
      pointDrag.dx = p.x - pointDrag.startX;
      pointDrag.dy = p.y - pointDrag.startY;
      pointMoves[pointMoves.length - 1] = pointDrag;
      draw();
      if (onStateChange) onStateChange();
    }
  }
  function endPointDrag(ev) {
    if (pointDrag) {
      pointDrag = null;
      draw();
      if (onStateChange) onStateChange();
    }
    canvas.releasePointerCapture && ev && canvas.releasePointerCapture(ev.pointerId);
  }

  canvas.addEventListener("pointerdown", (ev) => {
    if (editing) startPointDrag(ev);
  });
  canvas.addEventListener("pointermove", (ev) => {
    hover = pointerPos(ev);
    if (editing && pointDrag) movePointDrag(ev);
    draw();
  });
  canvas.addEventListener("pointerup", (ev) => {
    if (editing) endPointDrag(ev);
  });
  canvas.addEventListener("pointerleave", () => { hover = null; draw(); });
  canvas.addEventListener("pointercancel", (ev) => {
    if (editing) endPointDrag(ev);
  });

  return {
    get char() { return currentChar; },
    setChar(ch) { currentChar = ch; pointMoves = []; hover = null; draw(); },
    setEditing(on) { editing = !!on; hover = null; pointDrag = null; draw(); },
    getEditing() { return editing; },
    undo() {
      pointMoves.pop();
      pointDrag = null;
      draw();
    },
    reset() { pointMoves = []; pointDrag = null; draw(); },
    refresh() { draw(); },
    getGlyph() { return buildContours(); },
    getLiveDeltas() {
      const base = interpolateGlyph(getEmotionGlyfs(currentChar), getWeights());
      return pointMovesToDeltas(base.contours, pointMoves);
    },
    hasEdits() { return pointMoves.length > 0; },
    _testDraw() { return pointMoves; },
  };
}
/* ===== preview.js ===== */
// Anteprima della parola composta con le forme attuali

const YMIN = -780;
const YMAX = 90;

function createPreview(canvas, store, getWeights, resolveGlyph) {
  const ctx = canvas.getContext("2d");
  let raf = 0;

  // resolvaGlyph(ch) -> { contours, advance } | null

  function layoutInfo() {
    const word = input.value.trim();
    const items = [];
    let total = 0;
    for (const raw of word) {
      const g = resolveGlyph(raw);
      if (g) { items.push({ raw, g }); total += g.advance; }
      else { items.push({ raw, g: null }); total += 360; }
    }
    if (!total) total = items.length * 500;
    const W = canvas.width - 60, H = canvas.height - 40;
    const scale = Math.min(W / total, H / (YMAX - YMIN));
    const positions = [];
    let x0 = Math.max(24, (canvas.width - total * scale) / 2);
    for (const item of items) {
      positions.push(x0);
      x0 += (item.g ? item.g.advance : 360) * scale;
    }
    return { word, items, positions, x0, scale };
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const { items, positions, x0, scale } = layoutInfo();
    const yBase = canvas.height - 30; // riga di base in alto? no: basse in basso
    // le lettere salgono dalla baseline (0..-700 in font), quindi baseline verso il basso
    const color = blendColor(store.emotions, getWeights()).hex;

    for (let i = 0; i < items.length; i++) {
      const gx = positions[i];
      const item = items[i];
      if (!item.g) {
        // lettera non disponibile: disegna un quadratino
        ctx.fillStyle = "rgba(0,0,0,.18)";
        ctx.fillRect(gx + 30, yBase - 500 * scale, 140 * scale, 500 * scale);
        ctx.fillStyle = "#1d1d1b";
        ctx.font = `${Math.max(10, 120 * scale)}px sans-serif`;
        ctx.textAlign = "center";
        ctx.fillText(item.raw, gx + 100 * scale, yBase - 60 * scale);
        continue;
      }
      drawGlyph(item.g.contours, gx, yBase, scale, color);
    }

    // caret di scrittura dove andrà la prossima lettera, alto quanto i glifi reali
    if (document.activeElement === input) {
      let topY = -Infinity, botY = Infinity;
      for (const item of items) {
        if (!item.g) continue;
        for (const c of item.g.contours) for (const p of c) {
          if (p[1] < topY) topY = p[1];
          if (p[1] > botY) botY = p[1];
        }
      }
      const sel = Math.min(input.selectionStart ?? input.value.length, items.length);
      const cx = sel >= items.length ? x0 : positions[sel];
      if (Math.floor(Date.now() / 400) % 2 === 0) {
        ctx.fillStyle = "#c7442e";
        if (topY === -Infinity) {
          const cap = (YMAX - YMIN) * scale;
          ctx.fillRect(cx, yBase - cap, 3, cap);
        } else {
          const top = yBase - topY * scale;
          const bot = yBase - botY * scale;
          ctx.fillRect(cx, top, 3, Math.max(6, bot - top));
        }
      }
    }
  }

  function drawGlyph(contours, x0, yBase, scale, color) {
    ctx.fillStyle = color;
    ctx.strokeStyle = "rgba(0,0,0,.10)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const c of contours) {
      if (!c.length) continue;
      const sx = x0 + c[0][0] * scale;
      const sy = yBase - c[0][1] * scale;
      ctx.moveTo(sx, sy);
      for (let j = 1; j < c.length; j++) {
        ctx.lineTo(x0 + c[j][0] * scale, yBase - c[j][1] * scale);
      }
      ctx.closePath();
    }
    ctx.fill("evenodd");
    ctx.stroke();
  }

  // ridisegna su richiesta (debounce)
  function request() {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(draw);
  }

  // lampeggio continuo del caret mentre l'input è focalizzato
  let blinkRaf = 0;
  function blink() {
    if (document.activeElement !== input) { blinkRaf = 0; return; }
    request();
    blinkRaf = requestAnimationFrame(blink);
  }

  const input = document.getElementById("word-input");
  input.addEventListener("input", request);
  input.addEventListener("change", request);
  input.addEventListener("focus", () => { request(); blinkRaf = requestAnimationFrame(blink); });
  input.addEventListener("blur", () => { cancelAnimationFrame(blinkRaf); blinkRaf = 0; request(); });
  input.addEventListener("keyup", request);
  input.addEventListener("click", (e) => {
    if (typeof e.clientX !== "number") return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const { items, positions, x0 } = layoutInfo();
    let idx = items.length;
    for (let i = 0; i < items.length; i++) {
      const next = i + 1 < items.length ? positions[i + 1] : x0;
      const mid = (positions[i] + next) / 2;
      if (x < mid) { idx = i; break; }
    }
    if (input.selectionStart !== idx || input.selectionEnd !== idx) {
      input.setSelectionRange(idx, idx);
    }
    request();
  });
  if (document.addEventListener) document.addEventListener("selectionchange", request);

  return { request };
}
/* ===== ui.js ===== */
// Piccole funzioni UI: paletta lettere e stato dei contributi

function createPalette(container, store, editor, onSelect) {
  let active = null;
  const chips = [];
  for (const ch of store.charset) {
    if (ch === " ") continue;
    const b = document.createElement("button");
    b.className = "letter-chip";
    b.setAttribute("type", "button");
    b.textContent = ch;
    b.setAttribute("aria-label", `Lettera ${ch}`);
    const badge = document.createElement("span");
    badge.className = "letter-badge";
    b.appendChild(badge);
    b.addEventListener("click", () => {
      if (active) active.classList.remove("active");
      active = b;
      b.classList.add("active");
      onSelect(ch);
    });
    container.appendChild(b);
    chips.push({ ch, b, badge });
  }
  // seleziona la prima lettera
  const first = container.querySelector(".letter-chip");
  if (first) first.click();
  return {
    updateBadges(store, community, emotionId) {
      for (const { ch, badge } of chips) {
        const n = emotionId ? community.contributionCount(ch, emotionId) : 0;
        if (n > 0) {
          badge.textContent = n;
          badge.classList.add("show");
        } else {
          badge.textContent = "";
          badge.classList.remove("show");
        }
      }
    },
  };
}

function updateContributionState(store, community) {
  const el = document.getElementById("contribution-state");
  if (!el) return;
  const counts = [];
  for (const ch of store.charset) {
    const byEmotion = community.countsByEmotion(ch);
    const n = Object.values(byEmotion).reduce((a, b) => a + b, 0);
    if (n > 0) counts.push({ ch, n });
  }
  const total = counts.reduce((a, c) => a + c.n, 0);
  if (!total) {
    el.textContent = "Nessun contributo ancora salvato.";
    return;
  }
  const top = counts.slice().sort((a, b) => b.n - a.n).slice(0, 5);
  el.textContent =
    `${total} contributi su ${counts.length} lettere · ` +
    top.map((c) => `${c.ch}×${c.n}`).join(", ");
}
/* ===== main.js ===== */
// Avvio dell'app: collega pad, editor, anteprima, contributi ed esportazione

const $ = (id) => document.getElementById(id);

// Risolve la forma corrente di un carattere (emozione + contributi + disegno vivo)
function resolveGlyph(ch) {
  const norm = store.normalizeChar(ch);
  if (norm === null) return null;
  const base = interpolateGlyph(getEmotionGlyfs(norm), getWeights());
  return { contours: base.contours, advance: base.advance };
}

let pad, editor, preview, palette, chips;
let shapeCacheChar = null;
let shapeCache = null;
let applyEditingUIFn = null;

function invalidateShapes() {
  shapeCache = null;
  shapeCacheChar = null;
}

// Forma di ogni emozione = master dell'emozione + media dei suoi contributi.
// La lettera mostrata interpola tra queste forme modificate.
function getEmotionGlyfs(char) {
  if (shapeCacheChar === char && shapeCache) return shapeCache;
  const norm = store.normalizeChar(char);
  if (norm === null) return store.emotions.map(() => ({ c: [], a: 360 }));
  const glyfs = store.glyphsForChar(norm);
  shapeCache = store.emotions.map((e, i) => {
    const ew = store.emotions.map((_, j) => (j === i ? 1 : 0));
    const base = interpolateGlyph(glyfs, ew);
    const mean = community.contributionMean(norm, e.id);
    const c = mean ? applyDeltas(base.contours, mean) : base.contours;
    return { c, a: base.advance };
  });
  shapeCacheChar = char;
  return shapeCache;
}

function getActiveEmotionId() {
  const w = getWeights();
  for (let i = 0; i < store.emotions.length; i++) {
    const e = store.emotions[i];
    if (e.neutral) continue;
    if (w[i] >= 0.99) return e.id;
  }
  if (pad) {
    const p = pad.get();
    let best = null;
    let bestD = Infinity;
    for (const e of store.visibleEmotions) {
      const dx = p.x - e.pad.x;
      const dy = p.y - e.pad.y;
      const d = dx * dx + dy * dy;
      if (d < bestD) { bestD = d; best = e; }
    }
    if (best && bestD <= 0.25 * 0.25) return best.id;
  }
  return null;
}

// Sorgente dei pesi: "pad" (dal quadrato) o "manual" (slider percentuali).
// manualWeights: array di % (somma 100) parallelo a store.emotions.
let weightsSource = "pad";
let manualWeights = null;

function getWeights() {
  if (weightsSource === "manual" && manualWeights) {
    return manualWeights.map((v) => v / 100);
  }
  const p = pad.get();
  return weightsFromPad(p.x, p.y, store.emotions);
}

function currentColor() {
  return blendColor(store.emotions, getWeights()).hex;
}

function updateReadout() {
  const w = getWeights();
  const sorted = store.emotions
    .map((e, i) => ({ e, w: w[i] }))
    .sort((a, b) => b.w - a.w);
  $("pad-readout").textContent =
    sorted
      .filter((s) => s.w > 0.02)
      .map((s) => `${s.e.id} ${Math.round(s.w * 100)}%`)
      .join(" · ");
  const sw = $("color-swatch");
  const hex = $("color-hex");
  if (sw && hex) {
    const c = currentColor();
    sw.style.background = c;
    hex.textContent = c;
  }
}

let toastTimer = null;
function showToast(msg) {
  const el = $("toast");
  if (!el) return;
  el.textContent = msg;
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), 2200);
}

function drawGlyphThumb(canvas, contours, color) {
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, W, H);
  let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
  for (const c of contours) for (const p of c) {
    if (p[0] < xmin) xmin = p[0];
    if (p[0] > xmax) xmax = p[0];
    if (p[1] < ymin) ymin = p[1];
    if (p[1] > ymax) ymax = p[1];
  }
  if (!isFinite(xmin) || xmax <= xmin || ymax <= ymin) return;
  const pad = 14;
  const scale = Math.min((W - 2 * pad) / (xmax - xmin), (H - 2 * pad) / (ymax - ymin));
  const xmid = (xmin + xmax) / 2, ymid = (ymin + ymax) / 2;
  ctx.fillStyle = color;
  ctx.beginPath();
  for (const c of contours) {
    if (!c.length) continue;
    ctx.moveTo(W / 2 + (c[0][0] - xmid) * scale, H / 2 - (c[0][1] - ymid) * scale);
    for (let j = 1; j < c.length; j++) {
      ctx.lineTo(W / 2 + (c[j][0] - xmid) * scale, H / 2 - (c[j][1] - ymid) * scale);
    }
    ctx.closePath();
  }
  ctx.fill("evenodd");
}

let hintDismissed = false;
function syncEditorState() {
  const has = editor && editor.hasEdits();
  const undo = $("btnUndo"), reset = $("btnReset"), contrib = $("btnContribute");
  if (undo) undo.disabled = !has;
  if (reset) reset.disabled = !has;
  if (contrib) contrib.disabled = !has;
  const hint = $("editor-hint");
  if (hint) hint.classList.toggle("hidden", hintDismissed || has);
}

// ---- slider percentuali (pesi manuali) ----
let sliderInputs = [];
let sliderLabels = [];

function syncSliders() {
  const w = getWeights();
  for (let i = 0; i < sliderInputs.length; i++) {
    const pct = Math.round(w[i] * 100);
    sliderInputs[i].value = pct;
    sliderLabels[i].value = pct;
  }
}

// Ridistribuisce i pesi così la somma resta 100 quando si muove lo slider "idx".
// Strategia: il valore trascinato diventa v; gli altri vengono scalati
// proporzionalmente sul restante (100 - v).
function redistribute(idx, v) {
  if (!manualWeights) manualWeights = store.emotions.map(() => 0);
  const clamped = Math.max(0, Math.min(100, v));
  manualWeights[idx] = clamped;
  const others = store.emotions.map((_, i) => i).filter((i) => i !== idx);
  const rest = 100 - clamped;
  const sumOthers = others.reduce((s, i) => s + manualWeights[i], 0);
  if (sumOthers > 0) {
    const factor = rest / sumOthers;
    for (const i of others) manualWeights[i] *= factor;
  } else if (rest > 0) {
    // nessuno degli altri ha peso: distribuisci il resto in parti uguali
    const each = rest / others.length;
    for (const i of others) manualWeights[i] = each;
  }
  weightsSource = "manual";
}

function onManualChange(idx, value) {
  redistribute(idx, value);
  syncSliders();
  const pos = weightsToPad(manualWeights.map((v) => v / 100), store.emotions);
  pad.set(pos.x, pos.y, false);
  updateReadout();
  updateChipActive();
  applyEditingAvailability();
  syncBadges();
  editor.refresh();
  preview.request();
  updateEmotionTheme();
}

function buildWeightSliders() {
  const container = $("weight-sliders");
  sliderInputs = [];
  sliderLabels = [];
  store.emotions.forEach((e, i) => {
    const row = document.createElement("label");
    row.className = "weight-row";
    const name = document.createElement("span");
    name.className = "weight-name";
    name.innerHTML = `<span class="dot" style="background:${e.color}"></span>${e.id}`;
    const input = document.createElement("input");
    input.type = "range";
    input.min = 0; input.max = 100; input.step = 1;
    input.addEventListener("input", () => onManualChange(i, +input.value));
    const val = document.createElement("input");
    val.type = "number";
    val.className = "weight-num";
    val.min = 0; val.max = 100; val.step = 1;
    val.addEventListener("change", () => onManualChange(i, +val.value));
    row.appendChild(name);
    row.appendChild(input);
    row.appendChild(val);
    container.appendChild(row);
    sliderInputs.push(input);
    sliderLabels.push(val);
  });
  syncSliders();
}
function refreshAll() {
  editor.refresh();
  preview.request();
  updateContributionState(store, community);
  syncBadges();
}

function syncBadges() {
  if (palette) palette.updateBadges(store, community, getActiveEmotionId());
}

function updateChipActive() {
  const id = getActiveEmotionId();
  if (chips) Array.from(chips.children).forEach((c) => c.classList.toggle("active", c.dataset.emotion === id));
}

function applyEditingAvailability() {
  const can = !!getActiveEmotionId();
  const btn = $("btnEditing");
  if (btn) btn.disabled = !can;
  if (!can && editor && editor.getEditing()) {
    editor.setEditing(false);
    if (applyEditingUIFn) applyEditingUIFn(false);
    const hint = $("editor-hint");
    if (hint && !hintDismissed) hint.textContent = "Scegli un'emozione al 100% per modificare";
  }
}

async function boot() {
  try {
    await store.load();
  } catch (e) {
    $("pad").parentElement.insertAdjacentHTML(
      "beforeend",
      `<p class="error">Dati mancanti: avvia prima la pipeline Python (vedi README).</p>`
    );
    throw e;
  }

  pad = createPad($("pad"), store.visibleEmotions, () => {
    weightsSource = "pad";
    syncSliders();
    updateReadout();
    updateChipActive();
    applyEditingAvailability();
    syncBadges();
    editor.refresh();
    preview.request();
    updateEmotionTheme();
  });
  editor = createEditor($("editor"), store, getWeights, () => {
    preview.request();
    updateContributionState(store, community);
    syncEditorState();
  });
  preview = createPreview($("preview"), store, getWeights, resolveGlyph);

  buildWeightSliders();

  palette = createPalette($("letter-palette"), store, editor, (ch) => {
    editor.setChar(ch);
    refreshAll();
  });

  // emozioni rapide
  chips = $("emotion-chips");
  store.visibleEmotions.forEach((e) => {
    const b = document.createElement("button");
    b.className = "chip";
    b.setAttribute("type", "button");
    b.dataset.emotion = e.id;
    b.style.setProperty("--c", e.color);
    b.textContent = e.id;
    b.addEventListener("click", () => {
      pad.set(e.pad.x, e.pad.y);
      updateReadout();
      updateChipActive();
      applyEditingAvailability();
      syncBadges();
      refreshAll();
    });
    chips.appendChild(b);
  });
  updateChipActive();

  $("btnUndo").addEventListener("click", () => { editor.undo(); refreshAll(); syncEditorState(); });
  $("btnReset").addEventListener("click", () => { editor.reset(); refreshAll(); syncEditorState(); });

  // contributi
  $("btnContribute").addEventListener("click", () => {
    const emotionId = getActiveEmotionId();
    if (!emotionId) {
      const el = $("contribution-state");
      el.textContent = "Scegli un'emozione al 100% prima di contribuire.";
      el.classList.add("warn");
      setTimeout(() => el.classList.remove("warn"), 1500);
      return;
    }
    if (!editor.hasEdits()) {
      const el = $("contribution-state");
      el.textContent = "Sposta i punti sulla lettera prima di contribuire.";
      el.classList.add("warn");
      setTimeout(() => el.classList.remove("warn"), 1500);
      return;
    }
    const n = community.addContribution(editor.char, emotionId, editor.getLiveDeltas());
    invalidateShapes();
    editor.reset();
    refreshAll();
    syncBadges();
    syncEditorState();
    const el = $("contribution-state");
    el.textContent = `Contributo salvato per "${editor.char}" su ${emotionId} (totale ${n}).`;
    el.classList.add("ok");
    setTimeout(() => el.classList.remove("ok"), 2000);
    showToast(`Contributo salvato per "${editor.char}" su ${emotionId}`);
  });
  $("btnCommunity").addEventListener("click", () => {
    community.clearAllContributions();
    invalidateShapes();
    editor.reset();
    refreshAll();
    syncBadges();
    syncEditorState();
    $("contribution-state").textContent = "Contributi azzerati.";
    showToast("Contributi azzerati.");
  });

  // esportazione
  $("btnSvgLetter").addEventListener("click", () => {
    downloadSvg(exportLetter(editor.getGlyph(), currentColor()), `lettera-${editor.char}.svg`);
    showToast("SVG lettera scaricato.");
  });
  $("btnSvgWord").addEventListener("click", () => {
    const word = $("word-input").value;
    const items = word.split("").map((ch) => resolveGlyph(ch));
    downloadSvg(exportWord(items, currentColor()), "parola.svg");
    showToast("SVG parola scaricato.");
  });
  $("btnSvgAlphabet").addEventListener("click", () => {
    downloadSvg(exportAlphabet(store.charset, resolveGlyph, currentColor()), "alfabeto.svg");
    showToast("SVG alfabeto scaricato.");
  });
  $("btnFont").addEventListener("click", () => {
    downloadFont(
      buildFont(resolveGlyph, store.charset),
      "neoalfabeto-emotivo-cco.ttf"
    );
    showToast("Font TTF scaricato.");
  });

  // aiuto
  const dlg = $("helpDialog");
  $("btnHelp").addEventListener("click", () => dlg.showModal());
  $("btnCloseHelp").addEventListener("click", () => dlg.close());
  dlg.addEventListener("click", (e) => { if (e.target === dlg) dlg.close(); });

  // editing punti: i punti appaiono quando il bottone Editing è attivo
  const btnEditing = $("btnEditing");
  const applyEditingUI = (on) => {
    btnEditing.classList.toggle("active", on);
    btnEditing.setAttribute("aria-pressed", on ? "true" : "false");
    const hint = $("editor-hint");
    if (hint && !hintDismissed) {
      hint.textContent = on ? "Trascina i punti per deformare la lettera" : "Clicca Editing per modificare i punti";
    }
  };
  applyEditingUIFn = applyEditingUI;
  btnEditing.addEventListener("click", () => {
    if (!getActiveEmotionId()) {
      showToast("Scegli un'emozione al 100% per modificare la lettera");
      return;
    }
    const on = !editor.getEditing();
    editor.setEditing(on);
    applyEditingUI(on);
  });
  applyEditingUI(false);
  applyEditingAvailability();

  // hint editor: scompare da solo e non riappare più
  const hintEl = $("editor-hint");
  if (hintEl) {
    const dismissHint = () => {
      hintDismissed = true;
      hintEl.classList.add("hidden");
    };
    setTimeout(dismissHint, 4000);
    $("editor").addEventListener("pointerdown", dismissHint, { once: true });
  }

  $("editor").addEventListener("pointerdown", () => {
    if (!editor.getEditing()) {
      showToast(getActiveEmotionId()
        ? "Premi Editing per modificare i punti"
        : "Scegli un'emozione al 100% per modificare la lettera");
    }
  });

  // fullscreen canvas (mobile)
  const canvasFrame = $("canvas-frame");
  const btnFs = $("btnFullscreen");
  const editorCanvas = $("editor");
  if (canvasFrame && btnFs && editorCanvas) {
    const fsIcon = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/></svg>';
    const exitIcon = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3v3a2 2 0 0 1-2 2H3"/><path d="M21 8h-3a2 2 0 0 1-2-2V3"/><path d="M3 16h3a2 2 0 0 1 2 2v3"/><path d="M16 21v-3a2 2 0 0 1 2-2h3"/></svg>';

    const ORIG_W = 720, ORIG_H = 560;
    const ASPECT = ORIG_W / ORIG_H;

    function resizeCanvasForFullscreen() {
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      let newW, newH;
      if (vw / vh > ASPECT) {
        newH = Math.round(vh * 0.85);
        newW = Math.round(newH * ASPECT);
      } else {
        newW = Math.round(vw * 0.92);
        newH = Math.round(newW / ASPECT);
      }
      editorCanvas.width = newW;
      editorCanvas.height = newH;
    }

    function restoreCanvasSize() {
      editorCanvas.width = ORIG_W;
      editorCanvas.height = ORIG_H;
    }

    function enterFullscreen() {
      canvasFrame.classList.add("is-fullscreen");
      document.body.style.overflow = "hidden";
      btnFs.innerHTML = exitIcon;
      btnFs.setAttribute("aria-label", "Esci da schermo intero");
      resizeCanvasForFullscreen();
      setTimeout(() => editor.refresh(), 30);
    }
    function exitFullscreen() {
      canvasFrame.classList.remove("is-fullscreen");
      document.body.style.overflow = "";
      btnFs.innerHTML = fsIcon;
      btnFs.setAttribute("aria-label", "Schermo intero");
      restoreCanvasSize();
      setTimeout(() => editor.refresh(), 30);
    }

    btnFs.addEventListener("click", () => {
      if (canvasFrame.classList.contains("is-fullscreen")) {
        exitFullscreen();
      } else {
        enterFullscreen();
      }
    });

    document.addEventListener("fullscreenchange", () => {
      if (!document.fullscreenElement && canvasFrame.classList.contains("is-fullscreen")) {
        exitFullscreen();
      }
    });

    window.addEventListener("resize", () => {
      if (canvasFrame.classList.contains("is-fullscreen")) {
        resizeCanvasForFullscreen();
        editor.refresh();
      }
    });
  }

  updateReadout();
  updateContributionState(store, community);
  syncBadges();
  editor.refresh();
  preview.request();
  syncEditorState();
  updateEmotionTheme();
}

if (document.getElementById("editor")) {
  boot().catch((e) => console.error(e));
}